import React from 'react';
import './LatestStories.css';

const LatestStories = () => {
  const stories = [
    {
      id: 1,
      title: "10 Kitchen Design Trends for 2024",
      category: "Kitchen",
      readTime: "5 min read",
      image: "https://images.unsplash.com/photo-1556909114-f6e7ad7d3136?w=400&h=250&fit=crop",
      excerpt: "Discover the latest kitchen design trends that are shaping modern homes this year."
    },
    {
      id: 2,
      title: "Small Bathroom, Big Impact",
      category: "Bathroom",
      readTime: "3 min read",
      image: "https://images.unsplash.com/photo-1620626011761-996317b8d101?w=400&h=250&fit=crop",
      excerpt: "Transform your small bathroom into a luxurious retreat with these clever design ideas."
    },
    {
      id: 3,
      title: "Creating a Cozy Living Room",
      category: "Living Room",
      readTime: "4 min read",
      image: "https://images.unsplash.com/photo-1586023492125-27b2c045efd7?w=400&h=250&fit=crop",
      excerpt: "Learn how to make your living room the perfect place to relax and entertain guests."
    }
  ];

  return (
    <section className="latest-stories">
      <div className="container">
        <h2 className="section-title">Latest Stories</h2>
        <p className="section-subtitle">Get inspired with our latest home design articles and tips</p>
        
        <div className="stories-grid">
          {stories.map((story) => (
            <article key={story.id} className="story-card">
              <div className="story-image">
                <img src={story.image} alt={story.title} />
                <div className="story-category">{story.category}</div>
              </div>
              
              <div className="story-content">
                <h3 className="story-title">{story.title}</h3>
                <p className="story-excerpt">{story.excerpt}</p>
                <div className="story-meta">
                  <span className="read-time">{story.readTime}</span>
                  <button className="read-more-btn">Read More</button>
                </div>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
};

export default LatestStories;
